def transform(grid):
    """Extend a shorter repeated horizontal motif from its longer aligned copy.

    Rows with foreground content form separated bands. When two bands have the
    same leading motif (at least five matching columns) and one continues
    farther right, copy only its added foreground cells into the shorter band,
    marking the additions with 1.
    """
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    out = [row[:] for row in grid]
    best = None
    # Compare equally tall bands row-by-row; prioritize the longest shared
    # prefix, then the pair with the greatest difference in horizontal extent.
    for i in range(len(bands)):
        a0, a1 = bands[i]
        for j in range(i + 1, len(bands)):
            b0, b1 = bands[j]
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            common = 0
            for c in range(w):
                if all(grid[a0+k][c] == grid[b0+k][c] for k in range(height)):
                    common += 1
                else:
                    break
            if common < 5:
                continue
            end_a = max((c for rr in range(a0, a1) for c in range(w) if grid[rr][c] != bg), default=-1)
            end_b = max((c for rr in range(b0, b1) for c in range(w) if grid[rr][c] != bg), default=-1)
            if end_a == end_b:
                continue
            if end_a > end_b:
                src0, dst0, src_end, dst_end = a0, b0, end_a, end_b
            else:
                src0, dst0, src_end, dst_end = b0, a0, end_b, end_a
            key = (common, src_end - dst_end)
            if best is None or key > best[0]:
                best = (key, src0, dst0, height, common, src_end)

    if best is not None:
        _, src0, dst0, height, common, src_end = best
        for k in range(height):
            for c in range(common, src_end + 1):
                if grid[src0+k][c] != bg and grid[dst0+k][c] == bg:
                    out[dst0+k][c] = 1
    return out


if __name__ == "__main__":
    test = [
        [8]*27,
        [5,8,5,8,5,8,5,8,5,5,5,5,5,5,5]+[8]*12,
        [5,8,5,8,5,8,5,8,5,5,5,8,5,5,8,5,5,8]+[8]*9,
